//! Verbora vs. real, pinned third-party Rust competitors — stemmers.
//!
//! Reads `benches/data/stemmer-words.json`, generated by
//! `tools/bench-data/generate.py` — the same shared file every sibling
//! harness reads, so every implementation compared here runs on
//! byte-identical, realistic per-language vocabulary. See
//! `docs/COMPETITIVE_BENCHMARKS.md` §1.3 for the research dossier behind each
//! competitor choice below, and `../../README.md` for why this crate lives
//! outside the main workspace.
//!
//! # What is benchmarked, and why
//!
//! **Nine shared canonical-Snowball languages** (`de es fr it nl no pt ru
//! sv`) against TWO independent Snowball-family competitors, run side by side
//! so a reader can compare all three directly: `rust-stemmers` 1.2.0 and
//! `snowball_stemmers_rs` 1.0.1 — the matrix's own `Yes` rows ("Same
//! canonical Snowball algorithm"). Verified in
//! `../tests/stemmers_correctness.rs` before any timing number is trusted,
//! per the project's `CORRECTNESS BEFORE PERFORMANCE` rule: full agreement on
//! `de es fr it no pt sv`, on `ru` *except* words containing `ё` (see the
//! `ru` group's own comment, and `crates/verbora-stemmers/src/ru.rs`), and on
//! `nl` *only when a fresh [`PorterStemmerNl`] is used per word* (see the
//! `nl` group's own comment immediately below) — that is `rust-stemmers`'
//! own correctness picture, unchanged.
//!
//! `snowball_stemmers_rs` needs **no exclusions at all**: full, exact
//! agreement with Verbora on all nine languages, `ёлка` included — its own
//! `russian.sbl` carries the same `ё`→`е` pre-stemming fold Verbora's port
//! does, which `rust-stemmers` 1.2.0's vendored copy of the algorithm does
//! not (verified explicitly in
//! `../tests/stemmers_correctness.rs::russian_yo_fold_is_also_in_snowball_stemmers_rs`,
//! not merely assumed from matching crate names). Its Dutch needs
//! [`snowball_stemmers_rs::Algorithm::DutchPorter`], **not** the plain
//! `Algorithm::Dutch` — that crate ships *two* Dutch algorithms, and the
//! plainly-named one turns out to be a different, non-canonical stemmer
//! (Kraaij/Pohlmann, per `algorithms/dutch.sbl`'s own header comment), not
//! the one Verbora and `rust-stemmers` both implement; confirmed by direct
//! comparison in
//! `../tests/stemmers_correctness.rs::dutch_algorithm_variant_must_be_dutchporter_not_dutch`.
//! Like `rust-stemmers`, `snowball_stemmers_rs::Stemmer` carries no cross-call
//! state (`SnowballEnv` is built fresh inside every `stem()` call), so only
//! the Verbora side needs the fresh-instance-per-word discipline in the `nl`
//! group below.
//!
//! **Real result, per language, never averaged** (ratio range across `n` in
//! [`SIZES`], one `cargo bench -p competitive-rust --bench stemmers`
//! run — never an aggregate across languages, per this audit's own rule):
//! Verbora **wins** `de` (1.03×-1.39× faster than both) and `nl` vs.
//! `rust-stemmers` (1.69×-2.23× faster), but **loses** `nl` vs.
//! `snowball_stemmers_rs` (1.28×-1.44× slower) and loses every one of the
//! remaining seven languages against BOTH competitors: `es` (4.14×-5.29×
//! slower than `rust-stemmers`, 6.78×-7.70× slower than
//! `snowball_stemmers_rs`), `fr` (2.12×-2.48× / 2.82×-3.56×), `it`
//! (2.31×-2.52× / 2.70×-3.03×), `no` (5.17×-5.97× / 5.99×-7.75×), `pt`
//! (3.37×-4.50× / 6.47×-6.89×), `ru` (6.44×-9.61× / 6.20×-8.85×), `sv`
//! (5.17×-5.63× / 6.07×-7.07×). Read directly from
//! `crates/verbora-stemmers/src/units.rs`'s `longest_suffix`/`first_suffix`
//! (and each language's own local equivalent, e.g. `ru.rs`'s `alt_suffix`):
//! every language here does its "does this word end with any of these N
//! candidate suffixes" check with a **linear scan**, `for s in suffixes {ends_with(w, s)}`
//! — a direct, literal port of the reference's regex-alternation checks.
//! Both `rust-stemmers` and `snowball_stemmers_rs` are compiled by the
//! official Snowball compiler's Rust backend from the same `.sbl` source,
//! and that backend's shared runtime (`find_among`/`find_among_b`, see
//! `snowball_stemmers_rs-1.0.1/src/snowball/snowball_env.rs`) is a **binary
//! search** over a sorted candidate table with common-prefix tracking —
//! asymptotically cheaper, and it is called repeatedly per word (Spanish and
//! French alone call Verbora's linear-scan equivalent 19 and 43 times
//! respectively per `stem()`). German has zero `longest_suffix`/
//! `first_suffix` calls at all (it truncates by direct index instead) and
//! its suffix-literal table is the smallest of the nine (77 vs. 115-314
//! elsewhere) — consistent with it being the one language (alongside Dutch's
//! smaller table, 66 elements) where Verbora's simpler, allocation-lighter
//! approach comes out ahead.
//!
//! **English**, separately and clearly labeled, against TWO real Rust
//! alternatives so a reader can compare them directly: `nltk-porter` 0.1.0
//! in `Mode::Original` — the matrix's documented "closer algorithmic match,
//! but brand-new/unproven crate" — and `porter-stemmer` (samgiles) 0.1.2,
//! the best-adopted crate implementing the real original algorithm on
//! grapheme clusters rather than UTF-16 units. Neither is `rust-stemmers`,
//! used for English here: its "English" algorithm is Snowball Porter2, a
//! different algorithm from the original 1980 Porter Verbora implements
//! (matrix row marked `No`; see the crate-level doc comment on why that
//! pairing would not be a real comparison). Verified in
//! `../tests/stemmers_correctness.rs` before any timing number is trusted:
//! 64/64 agreement with `nltk-porter` on the realistic English word list plus
//! five inputs specifically chosen to trigger Verbora's own documented Porter
//! quirks (`measure`-as-float, no-early-exit `attemptReplacePatterns`,
//! empty-string-falsy — see `crates/verbora-stemmers/src/en.rs`'s own doc
//! comment); 63/64 agreement with `porter-stemmer` plus all five quirk
//! inputs — the grapheme-cluster-vs-UTF-16 architecture question the matrix
//! flagged turns out not to matter on this (plain-ASCII) corpus, but one
//! genuine, unrelated algorithm bug was found and confirmed (`"sky"` →
//! `"ski"`, where both Verbora and `nltk-porter` agree it should stay
//! `"sky"`) and is excluded from the shared benchmarked sample, exactly like
//! the `ru` group's own `ёлка`-filtering below. This is real, not
//! exhaustive, evidence: it resolves the matrix's "correctness vs. Verbora
//! unverified pre-benchmark" caveat for the corpus actually benchmarked, not
//! for every possible English string.
//!
//! **Japanese katakana** (`StemmerJa`), against `lindera-analysis` 5.2.0's
//! `JapaneseKatakanaStemTokenFilter` — the current, correctly-versioned real
//! package for this filter (the matrix names "the `lindera-filter`
//! sub-crate", but that package's own last release is 0.32.3 from
//! 2025-03-18: over a year stale, from before Lindera's 5.x rewrite folded
//! token/character filters into `lindera-analysis` instead — confirmed by
//! reading both crates' published source, not assumed; see `Cargo.toml`'s
//! own note on this row). Configured with `min = 3`, the filter's own
//! default and — per `../tests/stemmers_correctness.rs` — the exact value
//! that reproduces [`StemmerJa`]'s `>= 4`-UTF-16-unit threshold
//! (`chars().count() > 3 <=> >= 4` on this all-BMP-katakana domain). Only
//! ever exercised as an isolated filter call on manually-built,
//! pre-tokenized `Token`s from the shared `ja` katakana word list — never
//! through Lindera's own tokenizer/dictionary pipeline, per the matrix's own
//! fairness note.
//!
//! **Indonesian** (`StemmerId`), against `sastrawi` (iDevoid) 0.1.1 — genuine
//! shared PHP-Sastrawi lineage with Verbora's own port (both dictionaries
//! hold exactly 29,932 root words). `../tests/stemmers_correctness.rs` is the
//! real correctness pass the matrix's own dossier flagged as never having
//! been done, and it found two genuine algorithmic gaps versus the shared
//! reference: no hyphenated-reduplication/compound-plural handling at all,
//! and only a single (not iterated-up-to-3×) prefix-stripping pass. The three
//! words in the shared `id` word list that exercise those gaps are excluded
//! from the benchmarked sample here, leaving 13 of 16 words where both ports
//! agree byte-for-byte.
//!
//! # What is deliberately *not* benchmarked here
//!
//! * **`CarryStemmerFr` vs. `rust-stemmers::Algorithm::French`.** Confirmed
//!   by direct comparison during this bench's development: `rust-stemmers`'
//!   French is standard Snowball French, a different algorithm from the Carry
//!   variant (`"subitement"` → Carry `"subi"` vs. Snowball `"subit"`;
//!   `"publicité"` → Carry `"public"` vs. Snowball `"publiqu"`). Matrix row
//!   marked `No` — not benchmarked, per the "never benchmark a row marked No"
//!   rule.
//! * **`LancasterStemmer`, `PorterStemmerFa`, `PorterStemmerUk`.** Matrix's
//!   own `NO FAIR COMPETITOR FOUND` rows (Lancaster: only Rust port has ~25
//!   downloads and no independent verification pinned here; Farsi: Natural's
//!   own stemmer is a documented no-op, nothing to compare; Ukrainian: absent
//!   from `rust-stemmers`, no credible alternative found).
//!
//! # Shape
//!
//! One `benchmark_group` per language (mirrors `distance.rs`'s one-group-per-
//! metric convention). Within each group, `BenchmarkId::new(competitor, n)`
//! for `n` in [`SIZES`] — `n` words are stemmed per iteration, cycled from
//! that language's word list, throughput reported in elements (words). Every
//! call's input and output is wrapped in `black_box`.

use std::borrow::Cow;
use std::num::NonZeroUsize;

use criterion::{BenchmarkId, Criterion, Throughput, black_box, criterion_group, criterion_main};
use lindera::dictionary::{
    Dictionary as LinderaDictionary, WordId as LinderaWordId, load_dictionary,
};
use lindera::token::Token as LinderaToken;
use lindera_analysis::token_filter::TokenFilter as LinderaTokenFilter;
use lindera_analysis::token_filter::japanese_katakana_stem::JapaneseKatakanaStemTokenFilter;
use lindera_dictionary::viterbi::LexType;
use sastrawi::{Dictionary as SastrawiDictionary, Stemmer as SastrawiStemmer};

use verbora_stemmers::{
    PorterStemmer, PorterStemmerDe, PorterStemmerEs, PorterStemmerFr, PorterStemmerIt,
    PorterStemmerNl, PorterStemmerNo, PorterStemmerPt, PorterStemmerRu, PorterStemmerSv, StemmerId,
    StemmerJa,
};

/// Batch sizes: words stemmed per measured iteration, cycled from the
/// language's word list. Matches `distance.rs`'s `SIZES` so
/// `scripts/collect-results.py`'s hardcoded size set finds every directory.
const SIZES: [usize; 5] = [4, 16, 64, 256, 1024];

/// Reads `benches/data/stemmer-words.json`, failing loudly if it is missing.
fn load_words() -> serde_json::Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("repo root is 3 levels up from rust-competitors/")
        .join("benches/data/stemmer-words.json");
    let body = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {}: {e}\nGenerate it with: python3 tools/bench-data/generate.py",
            path.display()
        )
    });
    serde_json::from_str(&body).expect("valid bench data")
}

/// `n` words drawn cyclically from language `lang`'s list.
fn sample(words: &serde_json::Value, lang: &str, n: usize) -> Vec<String> {
    let list = words["languages"][lang]
        .as_array()
        .unwrap_or_else(|| panic!("no {lang:?} word list in stemmer-words.json"));
    list.iter()
        .cycle()
        .take(n)
        .map(|w| w.as_str().expect("string").to_owned())
        .collect()
}

/// One Criterion group per shared Snowball language: Verbora vs.
/// `rust-stemmers` vs. `snowball_stemmers_rs`, at every size in [`SIZES`].
macro_rules! snowball_group {
    ($fn_name:ident, $group:literal, $lang:literal, $verbora:ty, $algo:expr, $sn_algo:expr) => {
        fn $fn_name(c: &mut Criterion) {
            let data = load_words();
            let mut g = c.benchmark_group($group);
            let rs = rust_stemmers::Stemmer::create($algo);
            let sn = snowball_stemmers_rs::Stemmer::create($sn_algo);
            for n in SIZES {
                let words = sample(&data, $lang, n);
                g.throughput(Throughput::Elements(n as u64));
                g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
                    let s = <$verbora>::new();
                    bch.iter(|| {
                        words
                            .iter()
                            .map(|w| s.stem(black_box(w)).len())
                            .sum::<usize>()
                    });
                });
                g.bench_with_input(
                    BenchmarkId::new("rust-stemmers", n),
                    &words,
                    |bch, words| {
                        bch.iter(|| {
                            words
                                .iter()
                                .map(|w| rs.stem(black_box(w)).len())
                                .sum::<usize>()
                        });
                    },
                );
                g.bench_with_input(
                    BenchmarkId::new("snowball-stemmers-rs", n),
                    &words,
                    |bch, words| {
                        bch.iter(|| {
                            words
                                .iter()
                                .map(|w| sn.stem(black_box(w)).len())
                                .sum::<usize>()
                        });
                    },
                );
            }
            g.finish();
        }
    };
}

snowball_group!(
    bench_de,
    "porter_de",
    "de",
    PorterStemmerDe,
    rust_stemmers::Algorithm::German,
    snowball_stemmers_rs::Algorithm::German
);
snowball_group!(
    bench_es,
    "porter_es",
    "es",
    PorterStemmerEs,
    rust_stemmers::Algorithm::Spanish,
    snowball_stemmers_rs::Algorithm::Spanish
);
snowball_group!(
    bench_fr,
    "porter_fr",
    "fr",
    PorterStemmerFr,
    rust_stemmers::Algorithm::French,
    snowball_stemmers_rs::Algorithm::French
);
snowball_group!(
    bench_it,
    "porter_it",
    "it",
    PorterStemmerIt,
    rust_stemmers::Algorithm::Italian,
    snowball_stemmers_rs::Algorithm::Italian
);
snowball_group!(
    bench_no,
    "porter_no",
    "no",
    PorterStemmerNo,
    rust_stemmers::Algorithm::Norwegian,
    snowball_stemmers_rs::Algorithm::Norwegian
);
snowball_group!(
    bench_pt,
    "porter_pt",
    "pt",
    PorterStemmerPt,
    rust_stemmers::Algorithm::Portuguese,
    snowball_stemmers_rs::Algorithm::Portuguese
);
snowball_group!(
    bench_sv,
    "porter_sv",
    "sv",
    PorterStemmerSv,
    rust_stemmers::Algorithm::Swedish,
    snowball_stemmers_rs::Algorithm::Swedish
);

/// Dutch is its own function rather than going through the macro: unlike
/// every other stemmer here, [`PorterStemmerNl`] carries a **sticky**
/// `suffix_e_removed` flag that step 2 sets and step 3b reads, with nothing
/// ever resetting it (see `crates/verbora-stemmers/src/lib.rs`'s own doc
/// comment) — so `stem(word)` on one long-lived instance is not a pure
/// function of `word` alone, it also depends on every word stemmed earlier on
/// that *same instance*. Neither `rust-stemmers` nor `snowball_stemmers_rs`
/// has any equivalent state: both `stem()` calls are pure (the latter builds
/// a fresh `SnowballEnv` every call — confirmed by reading
/// `snowball_stemmers_rs-1.0.1/src/lib.rs`). Reusing one [`PorterStemmerNl`]
/// across a whole sampled batch (as the macro above does for the other eight
/// languages, and as `crates/verbora-stemmers/benches/stemmers.rs`'s own
/// `per_word` function does deliberately, to match the reference's real
/// module-singleton behavior) would make Verbora's answer for a given word
/// depend on cycle position — discovered directly during this bench's
/// development, when `stem("jongensgebaren")` differed between a standalone
/// check and a reused-instance benchmark run. A **fresh instance per word**,
/// `new()` being a cheap `const fn` that resets the flag, is what makes this
/// specific comparison a pure-function-vs-pure-function one, matching both
/// competitors' own semantics — verified in
/// `../tests/stemmers_correctness.rs`.
///
/// `snowball_stemmers_rs` uses [`snowball_stemmers_rs::Algorithm::DutchPorter`],
/// **not** the plainly-named `Algorithm::Dutch` — that crate's `Dutch` entry
/// is a genuinely different, non-canonical algorithm (Kraaij/Pohlmann), not
/// the one Verbora and `rust-stemmers` both implement; see the module doc
/// comment above and
/// `../tests/stemmers_correctness.rs::dutch_algorithm_variant_must_be_dutchporter_not_dutch`.
fn bench_nl(c: &mut Criterion) {
    let data = load_words();
    let mut g = c.benchmark_group("porter_nl");
    let rs = rust_stemmers::Stemmer::create(rust_stemmers::Algorithm::Dutch);
    let sn = snowball_stemmers_rs::Stemmer::create(snowball_stemmers_rs::Algorithm::DutchPorter);
    for n in SIZES {
        let words = sample(&data, "nl", n);
        g.throughput(Throughput::Elements(n as u64));
        g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| PorterStemmerNl::new().stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(
            BenchmarkId::new("rust-stemmers", n),
            &words,
            |bch, words| {
                bch.iter(|| {
                    words
                        .iter()
                        .map(|w| rs.stem(black_box(w)).len())
                        .sum::<usize>()
                });
            },
        );
        g.bench_with_input(
            BenchmarkId::new("snowball-stemmers-rs", n),
            &words,
            |bch, words| {
                bch.iter(|| {
                    words
                        .iter()
                        .map(|w| sn.stem(black_box(w)).len())
                        .sum::<usize>()
                });
            },
        );
    }
    g.finish();
}

/// Russian is its own function rather than going through the macro: `ёлка` is
/// filtered out of the shared word list before sampling, because Verbora
/// folds `ё`→`е` before stemming (`porter_stemmer_ru`'s own behavior) and
/// `rust-stemmers` does not — a real divergence outside the canonical
/// Snowball algorithm's scope, verified in
/// `../tests/stemmers_correctness.rs`. The shared list itself keeps `ёлка`
/// (it is a real word, and the in-workspace Verbora Criterion bench needs it)
/// — the exclusion happens here, once, by filtering rather than by omission
/// from the source of truth.
///
/// `snowball_stemmers_rs` does NOT need this exclusion — its own
/// `russian.sbl` carries the same `ё`→`е` fold Verbora's port does, verified
/// in
/// `../tests/stemmers_correctness.rs::russian_yo_fold_is_also_in_snowball_stemmers_rs`
/// — but per this module's own doc comment, every competitor in a group sees
/// byte-identical input, so it is benchmarked here on the same
/// `ёлка`-filtered list as `rust-stemmers`, not a wider one just because it
/// could handle more.
fn bench_ru(c: &mut Criterion) {
    let data = load_words();
    let mut g = c.benchmark_group("porter_ru");
    let rs = rust_stemmers::Stemmer::create(rust_stemmers::Algorithm::Russian);
    let sn = snowball_stemmers_rs::Stemmer::create(snowball_stemmers_rs::Algorithm::Russian);
    for n in SIZES {
        let words: Vec<String> = sample(&data, "ru", n * 2)
            .into_iter()
            .filter(|w| w != "ёлка")
            .take(n)
            .collect();
        g.throughput(Throughput::Elements(n as u64));
        g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
            let s = PorterStemmerRu::new();
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| s.stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(
            BenchmarkId::new("rust-stemmers", n),
            &words,
            |bch, words| {
                bch.iter(|| {
                    words
                        .iter()
                        .map(|w| rs.stem(black_box(w)).len())
                        .sum::<usize>()
                });
            },
        );
        g.bench_with_input(
            BenchmarkId::new("snowball-stemmers-rs", n),
            &words,
            |bch, words| {
                bch.iter(|| {
                    words
                        .iter()
                        .map(|w| sn.stem(black_box(w)).len())
                        .sum::<usize>()
                });
            },
        );
    }
    g.finish();
}

/// English: Verbora vs. TWO real Rust alternatives, `nltk-porter`
/// (`Mode::Original`) and `porter-stemmer` (samgiles) — see the crate doc
/// comment for why `rust-stemmers` is not used here, and for the one word
/// (`"sky"`) filtered out of the shared sample below because `porter-stemmer`
/// alone diverges on it (a real, isolated algorithm bug — both Verbora and
/// `nltk-porter` agree it should stay `"sky"`), mirroring `bench_ru`'s own
/// `ёлка`-filtering immediately above.
fn bench_en(c: &mut Criterion) {
    let data = load_words();
    let mut g = c.benchmark_group("porter_en");
    let nltk = nltk_porter::PorterStemmer::new(nltk_porter::Mode::Original);
    for n in SIZES {
        let words: Vec<String> = sample(&data, "en", n * 2)
            .into_iter()
            .filter(|w| w != "sky")
            .take(n)
            .collect();
        g.throughput(Throughput::Elements(n as u64));
        g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
            let s = PorterStemmer::new();
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| s.stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(BenchmarkId::new("nltk-porter", n), &words, |bch, words| {
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| nltk.stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(
            BenchmarkId::new("porter-stemmer", n),
            &words,
            |bch, words| {
                bch.iter(|| {
                    words
                        .iter()
                        .map(|w| porter_stemmer::stem(black_box(w)).len())
                        .sum::<usize>()
                });
            },
        );
    }
    g.finish();
}

/// Builds a bare, pre-tokenized [`LinderaToken`] for the isolated-filter
/// benchmark below. `word_id`/`dictionary` are structurally required by
/// [`LinderaToken`] but never read by `JapaneseKatakanaStemTokenFilter::apply`
/// itself (confirmed by reading `lindera-analysis-5.2.0/src/token_filter/
/// japanese_katakana_stem.rs`: it only ever touches `token.surface`) — a
/// fixed `Unknown` word id and one dictionary loaded ONCE outside every timed
/// closure below are enough to satisfy the type without smuggling any real
/// tokenizer/dictionary lookup into the measured region.
fn lindera_token<'a>(surface: &'a str, dictionary: &'a LinderaDictionary) -> LinderaToken<'a> {
    LinderaToken {
        surface: Cow::Borrowed(surface),
        byte_start: 0,
        byte_end: surface.len(),
        position: 0,
        position_length: 1,
        word_id: LinderaWordId::new(LexType::Unknown, 0),
        dictionary,
        user_dictionary: None,
        details: None,
    }
}

/// Japanese katakana: Verbora's [`StemmerJa`] vs. `lindera-analysis`
/// 5.2.0's `JapaneseKatakanaStemTokenFilter` (`min = 3`) — see the crate doc
/// comment for the package-naming story and why `min = 3` is the verified,
/// deliberate value, not a coincidence.
///
/// `TokenFilter::apply` takes `&mut Vec<Token>`, not a single string —
/// building that `Vec` (one [`LinderaToken`] per pre-tokenized word) is
/// unavoidable per-batch setup any real caller of this filter would also
/// pay, so it happens INSIDE each measured iteration here, mirroring
/// Verbora's own per-word `.stem()` call, which is also freshly invoked
/// every iteration — reusing one `Vec<Token>` across iterations would make
/// every iteration after the first a no-op (the mark is already stripped).
fn bench_ja(c: &mut Criterion) {
    let data = load_words();
    let mut g = c.benchmark_group("stemmer_ja");
    let dictionary = load_dictionary("embedded://ipadic")
        .expect("embedded IPADIC dictionary (lindera `embed-ipadic` feature)");
    let filter = JapaneseKatakanaStemTokenFilter::new(NonZeroUsize::new(3).expect("3 != 0"));
    for n in SIZES {
        let words = sample(&data, "ja", n);
        g.throughput(Throughput::Elements(n as u64));
        g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
            let s = StemmerJa::new();
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| s.stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(BenchmarkId::new("lindera", n), &words, |bch, words| {
            bch.iter(|| {
                let mut tokens: Vec<LinderaToken<'_>> = words
                    .iter()
                    .map(|w| lindera_token(black_box(w.as_str()), &dictionary))
                    .collect();
                filter
                    .apply(&mut tokens)
                    .expect("the filter never errors on plain-text tokens");
                tokens.iter().map(|t| t.surface.len()).sum::<usize>()
            });
        });
    }
    g.finish();
}

/// Indonesian: Verbora's [`StemmerId`] vs. `sastrawi` (iDevoid) 0.1.1 — see
/// the crate doc comment for the two real algorithmic gaps found and the
/// three words excluded from the shared sample below because of them.
fn bench_id(c: &mut Criterion) {
    let data = load_words();
    let mut g = c.benchmark_group("stemmer_id");
    /// Words where `sastrawi` (iDevoid) diverges from Verbora — see the
    /// crate doc comment and `../tests/stemmers_correctness.rs`.
    const EXCLUDED: [&str; 3] = ["buku-buku", "meniru-nirukan", "kesepersepuluhnya"];
    let dictionary = SastrawiDictionary::new();
    let stemmer = SastrawiStemmer::new(&dictionary);
    for n in SIZES {
        let words: Vec<String> = sample(&data, "id", n * 2)
            .into_iter()
            .filter(|w| !EXCLUDED.contains(&w.as_str()))
            .take(n)
            .collect();
        g.throughput(Throughput::Elements(n as u64));
        g.bench_with_input(BenchmarkId::new("verbora", n), &words, |bch, words| {
            let s = StemmerId::new();
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| s.stem(black_box(w)).len())
                    .sum::<usize>()
            });
        });
        g.bench_with_input(BenchmarkId::new("sastrawi", n), &words, |bch, words| {
            bch.iter(|| {
                words
                    .iter()
                    .map(|w| {
                        let mut owned = black_box(w).clone();
                        stemmer.stem_word(&mut owned);
                        owned.len()
                    })
                    .sum::<usize>()
            });
        });
    }
    g.finish();
}

criterion_group!(
    benches, bench_de, bench_es, bench_fr, bench_it, bench_nl, bench_no, bench_pt, bench_sv,
    bench_ru, bench_en, bench_ja, bench_id,
);
criterion_main!(benches);
